<?php $pageTitle='Review room import';$error=app()->session()->pullFlash('error'); ?>
<section class="page-heading"><div><p class="eyebrow">Validation preview</p><h1>Review room layouts</h1><p><?= e($batch['original_filename']) ?> contains <?= number_format((int)$batch['total_rows']) ?> room rows.</p></div><a class="secondary-button" href="<?= e(url('rooms/import')) ?>">Upload another file</a></section>
<?php if($error):?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif;?>
<section class="import-summary"><article><span>Ready</span><strong><?= number_format((int)$batch['valid_rows']) ?></strong></article><article><span>Invalid</span><strong><?= number_format((int)$batch['invalid_rows']) ?></strong></article><article><span>Status</span><strong><?= e(ucfirst($batch['status'])) ?></strong></article></section>
<section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Row</th><th>Room</th><th>Location</th><th>Geometry</th><th>Capacity</th><th>Disabled seats</th><th>Validation</th><th>Messages</th></tr></thead><tbody><?php foreach($rows as $row):$data=json_decode($row['normalized_data'],true);$messages=json_decode($row['validation_messages'],true)?:[];?><tr><td><?= (int)$row['row_number'] ?></td><td><strong><?= e($data['code']??'') ?></strong></td><td><?= e(($data['building']??'').(($data['floor']??'')?' / '.$data['floor']:'')) ?></td><td><?= (int)($data['rows_count']??0) ?> × <?= (int)($data['columns_count']??0) ?><small class="cell-note"><?= e(str_replace('_',' ',$data['seat_order']??'')) ?></small></td><td><strong><?= (int)($data['usable_capacity']??0) ?></strong><small class="cell-note">of <?= (int)($data['physical_capacity']??0) ?> usable</small></td><td><?= e(implode(', ',array_map(function($item){[$r,$c]=explode('-',$item);return sprintf('R%02d-C%02d',$r,$c);},$data['blocked']??[]))?:'None') ?></td><td><span class="status-label <?= e($row['validation_status']) ?>"><?= e(ucfirst($row['validation_status'])) ?></span></td><td><?= e(implode(' ',$messages)?:'Ready to import') ?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php if($batch['status']==='review'):?><form method="post" action="<?= e(url('rooms/import/'.$batch['id'].'/commit')) ?>" class="commit-bar"><?= csrf_field() ?><p><strong>Commit valid room layouts?</strong><span>Invalid rows remain in this validation report.</span></p><button class="primary-button" type="submit" <?= (int)$batch['valid_rows']===0?'disabled':'' ?>>Import <?= number_format((int)$batch['valid_rows']) ?> rooms</button></form><?php endif;?>
